package com.finsight.controller; import com.finsight.domain.Customer; import com.finsight.repository.CustomerRepository; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/customers") public class CustomerController {final CustomerRepository repo;public CustomerController(CustomerRepository r){repo=r;}@GetMapping public List<Customer> all(){return repo.findAll();}@GetMapping("/{id}")public Customer get(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Customer not found"));}}
